import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("$P/tests/server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("$P/tests/server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("$P/tests/server/_support/doubles/misc")).rateLimitModule);

import { emit } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { toAppError } from "@/lib/errors";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import * as projectService from "@/server/services/project-service";
import * as sessionService from "@/server/services/session-service";
import * as digestService from "@/server/services/digest-service";
import * as commentService from "@/server/services/comment-service";
import { notify, listNotifications } from "@/server/services/notification-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { createTenant, issueInput, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

describe("former members", () => {
  it("covers the scenarios", async () => {
    const t = await createTenant("ff", "growth");
    const other = await createTenant("ff-other", "growth");
    await memberRepo.insertMember(other.org.id, t.userIds.member, "member", null);
    await usageRepo.recomputeUsage(t.org.id);

    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member, dueAt: "2020-01-01T00:00:00.000Z" }));
    const led = await projectService.createProject(t.actors.owner, { orgId: t.org.id, name: "Led by member", slug: "led", key: "LED", description: null, visibility: "org", leadId: t.userIds.member, color: "#6366f1", targetDate: null });
    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.member, kind: "comment_created", inApp: true, email: true, digestOnly: true });
    expect(await digestService.listDigestRecipients(t.org.id)).toContain(t.userIds.member);

    const principal = await sessionRepo.createSession(t.userIds.member, "hash-ff", "2099-01-01T00:00:00.000Z" as never);
    const target = (await memberRepo.findMember(t.org.id, t.userIds.member))!;
    const seatsBefore = (await usageRepo.getUsage(t.org.id)).seatsUsed;

    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: target.id });
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(seatsBefore - 1);

    // 1. no acting / switching
    expect(await sessionService.resolveActorForOrg(principal, "ff")).toBeNull();
    await expect(sessionService.switchActiveOrg(principal, { orgId: t.org.id })).rejects.toThrow();
    expect(await memberService.resolveActor(t.userIds.member, t.org.id)).toBeNull();
    expect((await orgRepo.listOrgsForUser(t.userIds.member)).map((o) => o.id)).toEqual([other.org.id]);
    expect(await memberService.resolveActor(t.userIds.member, other.org.id)).not.toBeNull();

    // 4. cascade + refusals
    expect((await issueRepo.findIssueById(t.org.id, issue.id))!.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(t.org.id, led.id))!.leadId).toBeNull();
    expect((await projectRepo.findProjectById(other.org.id, other.project.id))!.leadId).toBe(other.userIds.owner);
    await expect(issueService.assignIssue(t.actors.admin, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.member })).rejects.toThrow(/not a member/);
    const countBefore = await issueRepo.countIssues(t.org.id, t.project.id);
    const e = await issueService.createIssue(t.actors.admin, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member })).catch((x) => x);
    expect(toAppError(e).code).toBe("validation_failed");
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(countBefore);
    await expect(issueService.assignIssue(t.actors.admin, { orgId: t.org.id, issueId: issue.id, assigneeId: other.userIds.admin })).rejects.toThrow();
    const projCount = await projectRepo.countProjects(t.org.id);
    await expect(projectService.createProject(t.actors.owner, { orgId: t.org.id, name: "Nope", slug: "nope", key: "NOPE", description: null, visibility: "org", leadId: t.userIds.member, color: "#6366f1", targetDate: null })).rejects.toThrow();
    expect(await projectRepo.countProjects(t.org.id)).toBe(projCount);
    await expect(projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, leadId: t.userIds.member, name: "renamed" })).rejects.toThrow();
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))!.name).not.toBe("renamed");

    // 3. notifications
    const rows = await notify(t.org.id, "comment_created", [t.userIds.member, t.userIds.admin], { title: "x", body: "x", href: "/", actorId: null });
    expect(rows.map((r) => r.recipientId)).toEqual([t.userIds.admin]);
    await emit("issue.overdue", { orgId: t.org.id, actorId: null, occurredAt: issue.createdAt, issueId: issue.id, projectId: issue.projectId, dueAt: issue.createdAt, assigneeId: t.userIds.member });
    const inbox = await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.member, unreadOnly: false, limit: 50, cursor: null });
    expect(inbox.items).toHaveLength(0);
    expect(await digestService.listDigestRecipients(t.org.id)).not.toContain(t.userIds.member);
    const c = await commentService.createComment(t.actors.admin, { orgId: t.org.id, issueId: issue.id, body: "hey @member", parentId: null, mentionedUserIds: [t.userIds.member] });
    expect(c.mentionedUserIds).toEqual([]);

    // 5. conflicts
    const seatsAfterRemove = (await usageRepo.getUsage(t.org.id)).seatsUsed;
    const r1 = await memberService.updateMemberRole(t.actors.owner, { orgId: t.org.id, memberId: target.id, role: "admin" }).catch((x) => x);
    expect(r1).toBeInstanceOf(AlreadyArchivedError);
    expect(toAppError(r1).code).toBe("conflict");
    await expect(memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: target.id })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(seatsAfterRemove);
    expect((await memberRepo.findMember(t.org.id, t.userIds.member))!.role).toBe("member");

    // 2. re-invite
    const token = "r".repeat(32);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "member@ff.test", role: "viewer", expiresInDays: 14 }, t.userIds.admin, hashToken(token));
    const back = await invitationService.acceptInvitation(t.userIds.member, { token });
    expect(back.id).toBe(target.id);
    expect(back.archivedAt).toBeNull();
    expect(back.role).toBe("viewer");
    expect(back.invitedBy).toBe(t.userIds.admin);
    expect(back.createdAt).toBe(target.createdAt);
    expect(back.joinedAt).not.toBe(target.joinedAt);
    const inv = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(inv!.acceptedAt).toBe(back.joinedAt);
    await expect(invitationService.acceptInvitation(t.userIds.member, { token })).rejects.toThrow(/already been accepted/);
    const list = await memberService.listMembers(t.actors.owner, { orgId: t.org.id, limit: 50, cursor: null });
    expect(list.items.filter((m) => m.userId === t.userIds.member)).toHaveLength(1);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(seatsBefore);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(4);
    expect(await memberService.resolveActor(t.userIds.member, t.org.id)).toMatchObject({ role: "viewer" });
    const again = await notify(t.org.id, "comment_created", [t.userIds.member], { title: "x", body: "x", href: "/", actorId: null });
    expect(again).toHaveLength(1);

    // current member accepts an invitation
    const token2 = "s".repeat(32);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "admin@ff.test", role: "viewer", expiresInDays: 14 }, t.userIds.owner, hashToken(token2));
    const seats2 = (await usageRepo.getUsage(t.org.id)).seatsUsed;
    const adminBefore = (await memberRepo.findMember(t.org.id, t.userIds.admin))!;
    const same = await invitationService.acceptInvitation(t.userIds.admin, { token: token2 });
    expect(same).toEqual(adminBefore);
    expect((await memberRepo.findMember(t.org.id, t.userIds.admin))).toEqual(adminBefore);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(seats2);
    await expect(invitationService.acceptInvitation(t.userIds.admin, { token: token2 })).rejects.toThrow(/already/);
  });
});
EOF
